-- Founder section on the public homepage. One jsonb document on the settings row, so every word, number,
-- colour and the photo are editable in Admin → Marketing Website → Founder (nothing hardcoded in the page).
-- The row is pre-filled once (only where it is still empty) from the founder's own CV and story; edit freely afterwards.

alter table platform_marketing_settings add column if not exists founder jsonb not null default '{}'::jsonb;

update platform_marketing_settings
set founder = $founder${"enabled":true,"eyebrow":"Meet the Founder","name":"Inder Kumar Bhatnagar","headline":"Real Estate Business & Learning Expert","role_line":"General Manager — Training & Development, InfraMantra India Pvt. Ltd.","tagline":"Real estate teams deserve training that comes from the field, not from a textbook.","photo_url":null,"bio":"Inder has spent 25+ years inside the real estate business — selling, leading sales teams, hiring, coaching and building the people who build revenue — across real estate, insurance, FMCG and logistics. For the last 12+ years he has turned that floor-level experience into structured learning: induction academies, product knowledge frameworks, sales excellence programs and leadership development.\n\nHe is the published author of two books — Training: A Myth – Let's Break It and Sell Like a Closer — and today leads Training & Development at InfraMantra India Pvt. Ltd., partnering with senior leadership to close capability gaps and tie learning to business results.\n\nRealTrainer is the product of that journey: everything he learned about training real estate professionals, packaged so any company can use it.","stats":[{"value":"25+","label":"Years of experience"},{"value":"12+","label":"Years in Learning & Development"},{"value":"16+","label":"Years in sales leadership"},{"value":"2","label":"Published books"},{"value":"4","label":"Industries"}],"expertise":["Learning Strategy & Design","Sales Transformation","Leadership Coaching","Capability Building","Sales Enablement","Induction & Onboarding","Performance Coaching","LMS & Digital Learning","AI-Enabled Learning","Business Development","Change Management","Customer Experience"],"industries":["Real Estate","Insurance","FMCG","Logistics"],"books":[{"title":"Training: A Myth — Let's Break It","blurb":"A practical guide for trainers, managers, HR professionals and business leaders — challenging how corporate training is usually done and focusing on learning that delivers measurable business outcomes."},{"title":"Sell Like a Closer","blurb":"A modern sales playbook built on practical industry experience: consultative selling, customer psychology, objection handling, negotiation, relationship building and ethical closing."}],"journey":[{"period":"Apr 2024 – Present","role":"General Manager — Training & Development","org":"InfraMantra India Pvt. Ltd.","note":"Enterprise-wide learning: Sales Induction Academy, product knowledge, sales excellence and leadership programs, with AI-enabled tracking."},{"period":"Aug 2022 – Apr 2024","role":"Head — Training & Development","org":"Realty Smartz Pvt. Ltd.","note":"Built induction and sales-enablement frameworks from the ground up."},{"period":"Jun 2021 – Aug 2022","role":"Sales Trainer","org":"Shoperty Consultant Pvt. Ltd.","note":"Practical modules on residential & commercial real estate, ROI, objection handling and negotiation."},{"period":"Mar 2020 – May 2021","role":"Corporate Trainer & Learning Consultant","org":"Freelance","note":"Corporate programs, seminars and behavioural workshops across India."},{"period":"Nov 2018 – Mar 2020","role":"Assistant General Manager — Sales","org":"Seedwill Consulting Pvt. Ltd.","note":"Led high-performing sales teams and business development."},{"period":"Mar 2015 – Nov 2018","role":"General Manager — Sales","org":"UrbanPlus Infrabuild Pvt. Ltd.","note":"End-to-end sales across multiple projects; built, hired and coached the teams."},{"period":"Mar 2012 – Mar 2015","role":"Sales Head — Investments","org":"Himalaya Realtors","note":"Residential and commercial sales with investment advisory."},{"period":"Apr 2010 – Mar 2012","role":"Senior Property Specialist","org":"Agni Property","note":"Primary real estate sales from lead generation to closure."},{"period":"Dec 2006 – Mar 2010","role":"Agency Manager","org":"Birla Sun Life Insurance","note":"Recruited, trained and coached advisors."},{"period":"Sep 2000 – Dec 2006","role":"Territory Manager","org":"Overnite Express Ltd.","note":"Territory sales, operations, collections and branch profitability."},{"period":"Nov 1998 – Aug 2000","role":"Sales Representative","org":"Fena Ltd.","note":"Started in FMCG sales, building distributor and retailer networks."}],"why_eyebrow":"Why RealTrainer exists","why_title":"Real estate has a training gap — and it is costing the industry its people","why_intro":"Most real estate companies don't invest in training their employees. The result is a revolving door: high attrition, constant fresh hiring, and the same learning curve paid for again and again.","gaps":[{"icon":"🔁","title":"No training, so people leave","text":"Employees who are not trained don't grow, don't feel invested in, and move on. Every exit means a new hire, a new ramp-up and a new cost."},{"icon":"🧑‍🏫","title":"Very few real estate trainers","text":"The industry has a genuine shortage of trainers — and many of those available bring theory or experience from other industries, not from the real estate floor."},{"icon":"🧭","title":"Theory is not practice","text":"Classroom concepts and the reality of site visits, objections, negotiation and closing are entirely different worlds. Practical exposure is what is missing."},{"icon":"💸","title":"Good trainers are out of reach","text":"An experienced trainer typically costs ₹6–12 lakh per year or more — beyond what most small and mid-size teams can afford."}],"compare_left_label":"A full-time experienced trainer","compare_left_value":"₹6–12 lakh+ / year","compare_left_note":"Still one person, one schedule, one batch at a time.","compare_right_label":"RealTrainer","compare_right_value":"Minimal cost","compare_right_note":"All the practical exposure — induction, projects, tests, certificates — for every employee, any time.","mission_quote":"Training should not be a luxury. Every real estate professional deserves practical, field-tested learning from day one.","cta_title":"See it in action","cta_text":"Connect with us for a live demo — our team will walk you through the platform with real, practical examples.","cta_label":"Book a live demo","bg_from":"#0B1B3A","bg_to":"#12274D","accent":"#D4A93A"}$founder$::jsonb
where founder = '{}'::jsonb;
